  assert.equal(FROM_SAFE_TEXT, SANITIZATION_FAILED);
  assert.equal(SANITIZATION_FAILED, "[diagnostic suppressed: credential sanitization failed]");
  assert.equal(redactDiagnosticForOutput("fine"), "fine");
});

